// Baut aus dem Fehlerobjekt eine kurze, lesbare Meldung.
//
// Bewusst NICHT verwendet: error.context, error.stack und
// error.description. Die tragen bei HTTP-Fehlern den kompletten Request
// samt apikey und Authorization im Klartext und sprengen jede Nachricht.
//
// Die Felder sind je nach Fehlerart verschieden: Bei einem HTTP-Fehler
// gibt es node, httpCode und name, beim Task-Timeout keines davon.
// Verlaesslich sind nur message, lastNodeExecuted und url - alles
// andere wird deshalb abgesichert gelesen.

const NL = String.fromCharCode(10);
const j = $input.first().json || {};
const ex = j.execution || {};
const wf = j.workflow || {};
const err = ex.error || {};

function text(v) {
  return String(v === null || v === undefined ? '' : v).trim();
}

const meldung = text(err.message) || 'Keine Meldung uebermittelt';
const code = text(err.httpCode);
const art = text(err.name);
const node = text(err.node && err.node.name);
const zuletzt = text(ex.lastNodeExecuted);
const m = meldung.toLowerCase();

// --- Einordnung: die spezifischste Regel zuerst ----------------------
let kennung = 'DATEN';

if (m.indexOf('task execution timed out') !== -1) {
  kennung = 'ZEITGRENZE';
} else if (m.indexOf('credential') !== -1 && m.indexOf('does not exist') !== -1) {
  kennung = 'ZUGANG';
} else if (code === '401' || code === '403') {
  kennung = 'ZUGANG';
} else if (code === 'ECONNRESET' || code === 'ETIMEDOUT' || code === 'ECONNREFUSED' || code === 'ENOTFOUND' || code === 'EAI_AGAIN' || code === 'EPIPE') {
  kennung = 'DIENST';
} else if (Number(code) >= 500) {
  kennung = 'DIENST';
} else if (Number(code) >= 400) {
  kennung = 'ANFRAGE';
}

const zeilen = [];
zeilen.push('[' + kennung + '] ' + (text(wf.name) || 'Unbekannter Workflow'));
zeilen.push('');

if (node) {
  zeilen.push('Node:    ' + node);
} else if (zuletzt) {
  zeilen.push('Node:    nicht benannt, zuletzt erfolgreich: ' + zuletzt);
} else {
  zeilen.push('Node:    nicht benannt');
}

if (code) {
  zeilen.push('Code:    ' + code + (art ? ' / ' + art : ''));
} else if (art) {
  zeilen.push('Art:     ' + art);
}

// Auf 300 Zeichen begrenzt - laengere Meldungen tragen keine
// zusaetzliche Information, nur Stapelspuren.
zeilen.push('Info:    ' + meldung.slice(0, 300));

if (node && zuletzt && node !== zuletzt) {
  zeilen.push('Zuletzt: ' + zuletzt);
}

zeilen.push('Lauf:    ' + text(ex.id) + (ex.mode ? ' (' + text(ex.mode) + ')' : ''));

if (ex.url) {
  zeilen.push(text(ex.url));
}

return [{
  json: {
    kennung: kennung,
    node: node || zuletzt || '',
    code: code,
    workflow: text(wf.name),
    lauf: text(ex.id),
    text: zeilen.join(NL)
  }
}];
